\label{tab:dose}
\begin{tabular}{@{}lcc@{}}
\toprule
\textbf{Injection Rate} & $\Delta$ \textbf{MMLU (pp)} & $\Delta$ \textbf{HellaSwag (pp)} \\
\midrule
10\% & 0.82 & 0.54 \\
30\% & 2.24 & 2.07 \\
50\% & 3.41 & 2.89 \\
